/// 8-bit-passthrough ESC handling (only reached with `eight == true`).
/// Returns the new `eight` value and bytes consumed, or `None` for
/// incomplete (truncated) input. Rules (all probed): `ESC ( B` clears the
/// flag (mode untouched); a pair-designation valid for the variant clears it
/// and designates when the underlying mode is a pair mode; anything else
/// emits `ESC` + the next byte literally and clears the flag; a trailing
/// lone `ESC` is emitted literally.
fn esc8(
    cfg: &IsoCfg,
    data: &[u8],
    i: usize,
    mode: IsoMode,
    s: &mut String,
) -> Option<(bool, IsoMode, usize)> {
    let rest = &data[i..];
    if rest.starts_with(b"\x1B(B") {
        return Some((false, mode, 3));
    }
    if matches!(mode, IsoMode::Pair(_))
        && (rest.starts_with(b"\x1B$B")
            || rest.starts_with(b"\x1B$@")
            || (rest.starts_with(b"\x1B$A") && cfg.ga)
            || (rest.starts_with(b"\x1B$(D") && cfg.d)
            || (rest.starts_with(b"\x1B$(O") && cfg.o)
            || (rest.starts_with(b"\x1B$(P") && cfg.p)
            || (rest.starts_with(b"\x1B$(Q") && cfg.q)
            || (rest.starts_with(b"\x1B$(C") && cfg.ks))
    {
        let pl = if rest[2] == b'$' {
            match rest[3] {
                b'B' | b'@' => IsoPlane::J208,
                b'A' => IsoPlane::A,
                _ => match rest[4] {
                    b'D' => IsoPlane::D,
                    b'O' => IsoPlane::O,
                    b'P' => IsoPlane::P,
                    b'Q' => IsoPlane::Q,
                    _ => IsoPlane::C,
                },
            }
        } else {
            // Unreachable: only `$` forms reach here, but stay total.
            IsoPlane::J208
        };
        let n = if rest[2] == b'$' && rest[3] == b'(' { 4 } else { 3 };
        return Some((false, IsoMode::Pair(pl), n));
    }
    if data.len() - i >= 2 {
        s.push('\u{1B}');
        s.push(data[i + 1] as char);
        // A fresh trigger byte re-arms the flag (probed `1B2B` chains);
        // `(`, `$`, `.`, `{0x26,0x29}|{0x40-0x5A}` clear it.
        Some((iso_trigger(data[i + 1]), mode, 2))
    } else {
        s.push('\u{1B}');
        Some((false, mode, 1))
    }
}

/// Non-KR ISO-2022 loop. 7-bit modes behave per `iso_single`/`iso_pair`;
/// `ESC X` with a trigger byte (`iso_trigger`) additionally sets the 8-bit
/// passthrough flag, under which every non-ESC byte is latin-1 (probed).
fn dec_iso(data: &[u8], strict: bool, cfg: &IsoCfg) -> Option<String> {
    let mut s = String::new();
    let mut i = 0;
    let mut mode = IsoMode::Single(IsoSingle::Ascii);
    let mut eight = false;
    while i < data.len() {
        let b = data[i];
        if eight {
            // 8-bit passthrough: every non-ESC byte is latin-1, except
            // `0x40-0x5A` (`@A-Z`) which is emitted and exits the flag
            // (probed exit grid).
            if b != 0x1B {
                s.push(b as char);
                i += 1;
                if (0x40..=0x5A).contains(&b) {
                    eight = false;
                }
                continue;
            }
            match esc8(cfg, data, i, mode, &mut s) {
                Some((e8, m, n)) => {
                    eight = e8;
                    mode = m;
                    i += n;
                }
                None => {
                    if strict {
                        return None;
                    } else {
                        break;
                    }
                }
            }
            continue;
        }
        if b == 0x1B {
            match iso_esc(cfg, data, i) {
                EscAction::Set(m) => {
                    // Designations are 3 bytes except `ESC $ ( X` (4 bytes).
                    i += if data[i + 1] == b'$' && data.get(i + 2) == Some(&b'(') {
                        4
                    } else {
                        3
                    };
                    mode = m;
                }
                EscAction::Bad => {
                    if strict {
                        return None;
                    } else {
                        i += bad_skip(data, i);
                    }
                }
                EscAction::EscByte(c) => {
                    s.push('\u{1B}');
                    s.push(c as char);
                    i += 2;
                    eight = iso_trigger(c);
                }
                EscAction::Incomplete => {
                    if strict {
                        return None;
                    } else {
                        break;
                    }
                }
            }
            continue;
        }
        match mode {
            IsoMode::Single(k) => {
                if b < 0x80 {
                    match iso_single(k, b) {
                        Some(c) => {
                            s.push(c);
                            i += 1;
                        }
                        None => {
                            if strict {
                                return None;
                            } else {
                                i += 1;
                            }
                        }
                    }
                } else if strict {
                    return None;
                } else {
                    i += 1;
                }
            }
            IsoMode::Pair(pl) => {
                if b < 0x20 {
                    s.push(b as char);
                    i += 1;
                } else if b <= 0x7E {
                    if i + 1 >= data.len() {
                        if strict {
                            return None;
                        } else {
                            break;
                        }
                    }
                    match iso_pair(pl, b, data[i + 1]) {
                        Some(e) => {
                            push_emit(&mut s, e);
                            i += 2;
                        }
                        None => {
                            if strict {
                                return None;
                            } else {
                                i += 2;
                            }
                        }
                    }
                } else if strict {
                    return None;
                } else {
                    i += 1;
                }
            }
        }
    }
    Some(s)
}

/// `iso2022_kr`: SO invokes ASCII (G1), SI invokes KS (G0) if designated;
/// designations never change the invocation (probed `0E 1B$(C AB` -> `AB`).
/// SO/SI toggle only in 7-bit mode (in 8-bit passthrough they are literal);
/// `ESC ( B` in 8-bit clears the flag without touching `g0ks` (probed).
fn dec_iso_kr(data: &[u8], strict: bool) -> Option<String> {
    let mut s = String::new();
    let mut i = 0;
    let mut g0ks = false;
    let mut g1ks = false;
    let mut g1 = false;
    let mut eight = false;
    while i < data.len() {
        let b = data[i];
        if eight {
            if b != 0x1B {
                s.push(b as char);
                i += 1;
                if (0x40..=0x5A).contains(&b) {
                    eight = false;
                }
                continue;
            }
            let rest = &data[i..];
            if rest.starts_with(b"\x1B(B") {
                eight = false;
                i += 3;
            } else if g0ks && !g1 && rest.starts_with(b"\x1B$(C") {
                eight = false;
                i += 4;
            } else if data.len() - i >= 2 {
                s.push('\u{1B}');
                s.push(data[i + 1] as char);
                eight = iso_trigger(data[i + 1]);
                i += 2;
            } else {
                s.push('\u{1B}');
                eight = false;
                i += 1;
            }
            continue;
        }
        if b == 0x0E {
            g1 = true;
            i += 1;
            continue;
        }
        if b == 0x0F {
            g1 = false;
            i += 1;
            continue;
        }
        if b == 0x1B {
            // `ESC $ ) C` designates KS to G1 (invoked by SO); `ESC $ ( C`
            // designates G0. Probed: `$)C SO GQ` -> KS, `$(C SO GQ` -> ASCII
            // pair path stays literal, `$(C SI AB` -> KS.
            if data[i..].starts_with(b"\x1B$)C") {
                g1ks = true;
                i += 4;
                continue;
            }
            match iso_esc(&ISO_KR, data, i) {
                EscAction::Set(m) => match m {
                    IsoMode::Single(IsoSingle::Ascii) => {
                        g0ks = false;
                        i += 3;
                    }
                    IsoMode::Pair(IsoPlane::C) => {
                        g0ks = true;
                        i += 4;
                    }
                    _ => {
                        if strict {
                            return None;
                        } else {
                            i += 3;
                        }
                    }
                },
                EscAction::Bad => {
                    if strict {
                        return None;
                    } else {
                        i += bad_skip(data, i);
                    }
                }
                EscAction::EscByte(c) => {
                    s.push('\u{1B}');
                    s.push(c as char);
                    i += 2;
                    eight = iso_trigger(c);
                }
                EscAction::Incomplete => {
                    if strict {
                        return None;
                    } else {
                        break;
                    }
                }
            }
            continue;
        }
        // Invoked set is G1 after SO, G0 after SI; KS decodes only when the
        // invoked set was designated KS (`$)C` -> G1, `$(C` -> G0).
        let ks_active = if g1 { g1ks } else { g0ks };
        if !ks_active {
            if b < 0x80 {
                s.push(b as char);
                i += 1;
            } else if strict {
                return None;
            } else {
                i += 1;
            }
        } else if b < 0x20 {
            s.push(b as char);
            i += 1;
        } else if b <= 0x7E {
            if i + 1 >= data.len() {
                if strict {
                    return None;
                } else {
                    break;
                }
            }
            match iso_pair(IsoPlane::C, b, data[i + 1]) {
                Some(e) => {
                    push_emit(&mut s, e);
                    i += 2;
                }
                None => {
                    if strict {
                        return None;
                    } else {
                        i += 2;
                    }
                }
            }
        } else if strict {
            return None;
        } else {
            i += 1;
        }
    }
    Some(s)
}

const ISO_KR: IsoCfg = IsoCfg {
    roman: false,
    kata: false,
    dot_a: false,
    dot_f: false,
    dega: false,
    b: false,
    d: false,
    o: false,
    p: false,
    q: false,
    ga: false,
    ks: true,
};
